pub fn assigns_of(nodes: &[u8], text: &[u8], a: usize, b: usize, va: usize, vb: usize) -> usize {
    let mut n: usize = 0;
    let mut j: usize = a;
    while (j < b) {
        if (((kind(nodes, j) == K_STMT_ASSIGN) && ((j + 1) < end(nodes, j))) && ident_is(nodes, text, (j + 1), &text[(va) as usize..(vb) as usize])) {
            n = (n + 1);
        }
        j = (j + 1);
    }
    return n;
}

pub fn binds(ps: &[u8], a: usize, b: usize, text: &[u8], ia: usize, ib: usize, fa: usize, fb: usize) -> bool {
    let n: usize = (ib - ia);
    let m: usize = (fb - fa);
    if ((b - a) != ((n + 1) + m)) {
        return false;
    }
    if !(has_at(ps, a, (a + n), &text[(ia) as usize..(ib) as usize])) {
        return false;
    }
    if (ps[((a + n)) as usize] != 95) {
        return false;
    }
    return has_at(ps, ((a + n) + 1), b, &text[(fa) as usize..(fb) as usize]);
}

pub fn colon_at(ptext: &[u8], s: usize, e: usize) -> usize {
    let mut j: usize = s;
    while ((j < e) && (ptext[(j) as usize] != B_COLON_V)) {
        j = (j + 1);
    }
    return j;
}

pub fn digit_of(c: u8) -> u64 {
    if ((c >= 48) && (c <= 57)) {
        return ((c - 48) as u64);
    }
    if ((c >= 97) && (c <= 102)) {
        return ((c - 87) as u64);
    }
    if ((c >= 65) && (c <= 70)) {
        return ((c - 55) as u64);
    }
    return 99;
}

pub fn find_decl(nodes: &[u8], text: &[u8], a: usize, b: usize) -> i64 {
    let mut c: usize = 1;
    while (c < end(nodes, 0)) {
        let k: u8 = kind(nodes, c);
        if (((k == K_CONST_DECL) || (k == K_STRUCT_DECL)) && field_is(nodes, text, c, F_NAME, &text[(a) as usize..(b) as usize])) {
            let ci: i64 = (c as _);
            return ci;
        }
        c = end(nodes, c);
    }
    return NO_NODE;
}

pub fn find_fn(nodes: &[u8], text: &[u8], a: usize, b: usize) -> i64 {
    let mut c: usize = 1;
    while (c < end(nodes, 0)) {
        if ((kind(nodes, c) == K_FN_DECL) && field_is(nodes, text, c, F_NAME, &text[(a) as usize..(b) as usize])) {
            let ci: i64 = (c as _);
            return ci;
        }
        c = end(nodes, c);
    }
    return NO_NODE;
}

pub fn fits(v: u64, t: i64) -> bool {
    if (t == TY_BOOL) {
        return (v <= 1);
    }
    if ty_int(t) {
        return (v <= max_of(t));
    }
    return false;
}

pub fn fold_ok_op(s: &[u8], a: u64, b: u64) -> bool {
    if (same(s, "+") || same(s, "+%")) {
        return (a <= (U64_MAX - b));
    }
    if (same(s, "-") || same(s, "-%")) {
        return (a >= b);
    }
    if (same(s, "*") || same(s, "*%")) {
        return ((b == 0) || (a <= (U64_MAX / b)));
    }
    if (same(s, "/") || same(s, "%")) {
        return (b != 0);
    }
    if same(s, "<<") {
        return ((b < 64) && (a <= (U64_MAX >> b)));
    }
    if (((same(s, ">>") || op_bitwise(s)) || (op_class(s) == OP_CMP)) || (op_class(s) == OP_LOGIC)) {
        return true;
    }
    return false;
}

pub fn fold_val_op(s: &[u8], a: u64, b: u64) -> u64 {
    if (same(s, "+") || same(s, "+%")) {
        return (a + b);
    }
    if (same(s, "-") || same(s, "-%")) {
        return (a - b);
    }
    if (same(s, "*") || same(s, "*%")) {
        return (a * b);
    }
    if same(s, "/") {
        return (a / b);
    }
    if same(s, "%") {
        return (a % b);
    }
    if same(s, "<<") {
        return (a << b);
    }
    if same(s, ">>") {
        if (b >= 64) {
            return 0;
        }
        return (a >> b);
    }
    if same(s, "&") {
        return (a & b);
    }
    if same(s, "|") {
        return (a | b);
    }
    if same(s, "^") {
        return (a ^ b);
    }
    let mut t: bool = false;
    if same(s, "==") {
        t = (a == b);
    }
    if same(s, "!=") {
        t = (a != b);
    }
    if same(s, "<") {
        t = (a < b);
    }
    if same(s, "<=") {
        t = (a <= b);
    }
    if same(s, ">") {
        t = (a > b);
    }
    if same(s, ">=") {
        t = (a >= b);
    }
    if (same(s, "and") || same(s, "&&")) {
        t = ((a == 1) && (b == 1));
    }
    if (same(s, "or") || same(s, "||")) {
        t = ((a == 1) || (b == 1));
    }
    if t {
        return 1;
    }
    return 0;
}

pub fn implicit_port(s: &[u8]) -> bool {
    return ((same(s, "clk") || same(s, "rst_n")) || same(s, "en"));
}

pub fn is_extern(nodes: &[u8], i: usize) -> bool {
    return ((kind(nodes, i) == K_FN_DECL) && (end(nodes, i) == (i + 1)));
}

pub fn is_instance(nodes: &[u8], text: &[u8], meta: &[u8], i: usize) -> bool {
    if (((kind(nodes, i) != K_CONST_DECL) || is_mut(meta, i)) || ((i + 1) >= end(nodes, i))) {
        return false;
    }
    if ((end(nodes, (i + 1)) != end(nodes, i)) || (kind(nodes, (i + 1)) != K_EXPR_CALL)) {
        return false;
    }
    let f: i64 = find_fn(nodes, text, lo(nodes, (i + 1), F_NAME), hi(nodes, (i + 1), F_NAME));
    if (f == NO_NODE) {
        return false;
    }
    let fi: usize = (f as _);
    return is_extern(nodes, fi);
}

pub fn is_mut(meta: &[u8], i: usize) -> bool {
    return ((meta_word(meta, i, 0) & FLAG_MUT) == FLAG_MUT);
}

pub fn is_pub(meta: &[u8], i: usize) -> bool {
    return ((meta_word(meta, i, 0) & FLAG_PUB) == FLAG_PUB);
}

pub fn kind_label(k: u8) -> &'static str {
    let ki: usize = (k as usize);
    if (ki < 35) {
        return KIND_NAMES[(ki) as usize];
    }
    return "node";
}

pub fn line_of(meta: &[u8], i: usize) -> usize {
    return meta_word(meta, i, 1);
}

pub fn line_stop(ptext: &[u8], s: usize, b: usize) -> usize {
    let mut j: usize = s;
    while ((j < b) && (ptext[(j) as usize] != B_NL)) {
        j = (j + 1);
    }
    return j;
}

pub fn lit_ok(s: &[u8], a: usize, b: usize) -> bool {
    return (lit_scan(s, a, b, true) == 1);
}

pub fn lit_radix(s: &[u8], a: usize, b: usize) -> u64 {
    if (((b - a) < 3) || (s[(a) as usize] != 48)) {
        return 10;
    }
    let c1: u8 = s[((a + 1)) as usize];
    if ((c1 == 120) || (c1 == 88)) {
        return 16;
    }
    if (c1 == 111) {
        return 8;
    }
    if (c1 == 98) {
        return 2;
    }
    return 10;
}

pub fn lit_scan(s: &[u8], a: usize, b: usize, check: bool) -> u64 {
    if (b <= a) {
        return 0;
    }
    let base: u64 = lit_radix(s, a, b);
    let mut j: usize = a;
    if (base != 10) {
        j = (a + 2);
    }
    let mut v: u64 = 0;
    let mut digits: usize = 0;
    while (j < b) {
        let c: u8 = s[(j) as usize];
        if (c != 95) {
            let d: u64 = digit_of(c);
            if (d >= base) {
                return 0;
            }
            if (v > ((U64_MAX - d) / base)) {
                return 0;
            }
            v = ((v * base) + d);
            digits = (digits + 1);
        }
        j = (j + 1);
    }
    if (digits == 0) {
        return 0;
    }
    if check {
        return 1;
    }
    return v;
}

pub fn lit_val(s: &[u8], a: usize, b: usize) -> u64 {
    return lit_scan(s, a, b, false);
}

pub fn loop_block(nodes: &[u8], text: &[u8], w: usize, name: &'static str) -> i64 {
    let mut c: usize = (w + 1);
    while (c < end(nodes, w)) {
        if ((kind(nodes, c) == K_MODULE) && field_eq(nodes, text, c, F_NAME, name)) {
            let ci: i64 = (c as _);
            return ci;
        }
        c = end(nodes, c);
    }
    return NO_NODE;
}

pub fn max_of(w: i64) -> u64 {
    let mut m: u64 = 0;
    let mut j: i64 = 0;
    while ((j < w) && (j < 64)) {
        m = ((m * 2) + 1);
        j = (j + 1);
    }
    return m;
}

pub fn meta_word(meta: &[u8], i: usize, w: usize) -> usize {
    return u32_at(meta, ((i * META) + (w * 4)));
}

pub fn op_bitwise(s: &[u8]) -> bool {
    return ((same(s, "&") || same(s, "|")) || same(s, "^"));
}

pub fn op_class(s: &[u8]) -> u8 {
    if ((((same(s, "+") || same(s, "-")) || same(s, "*")) || same(s, "/")) || same(s, "%")) {
        return OP_ARITH;
    }
    if ((same(s, "+%") || same(s, "-%")) || same(s, "*%")) {
        return OP_ARITH;
    }
    if ((same(s, "&") || same(s, "|")) || same(s, "^")) {
        return OP_ARITH;
    }
    if (same(s, "<<") || same(s, ">>")) {
        return OP_SHIFT;
    }
    if (((((same(s, "==") || same(s, "!=")) || same(s, "<")) || same(s, "<=")) || same(s, ">")) || same(s, ">=")) {
        return OP_CMP;
    }
    if (((same(s, "and") || same(s, "or")) || same(s, "&&")) || same(s, "||")) {
        return OP_LOGIC;
    }
    return OP_BAD;
}

pub fn own_continue(nodes: &[u8], a: usize, b: usize) -> bool {
    let mut j: usize = a;
    while (j < b) {
        let k: u8 = kind(nodes, j);
        if (((k == K_STMT_WHILE) || (k == K_STMT_FOR)) || (k == K_STMT_FOR_RANGE)) {
            j = end(nodes, j);
        } else {
            if (k == K_STMT_CONTINUE) {
                return true;
            }
            j = (j + 1);
        }
    }
    return false;
}

pub fn param_at(ptext: &[u8], a: usize, b: usize, k: usize) -> usize {
    let mut seen: usize = 0;
    let mut j: usize = a;
    while ((j < b) && (seen < k)) {
        if (ptext[(j) as usize] == B_NL) {
            seen = (seen + 1);
        }
        j = (j + 1);
    }
    return j;
}

pub fn param_count(ptext: &[u8], a: usize, b: usize) -> usize {
    let mut n: usize = 0;
    let mut j: usize = a;
    while (j < b) {
        if (ptext[(j) as usize] == B_NL) {
            n = (n + 1);
        }
        j = (j + 1);
    }
    return n;
}

pub fn param_role(name: &[u8], t: i64) -> u8 {
    if (((t == TY_STR) || (t == TY_FLOAT)) || (t == TY_COMPTIME)) {
        return ROLE_PARAM;
    }
    if ((t == TY_BOOL) && (same(name, "keep") || same(name, "dont_touch"))) {
        return ROLE_ATTR;
    }
    if ty_scalar(t) {
        return ROLE_PORT;
    }
    return ROLE_BAD;
}

pub fn params_hi(meta: &[u8], i: usize) -> usize {
    return meta_word(meta, i, 3);
}

pub fn params_lo(meta: &[u8], i: usize) -> usize {
    return meta_word(meta, i, 2);
}

pub fn peer(a: i64, b: i64) -> i64 {
    if (a == TY_COMPTIME) {
        if ((b == TY_COMPTIME) || ty_scalar(b)) {
            return b;
        }
        return TY_BAD;
    }
    if (b == TY_COMPTIME) {
        if ty_scalar(a) {
            return a;
        }
        return TY_BAD;
    }
    if ((a == TY_BOOL) && (b == TY_BOOL)) {
        return TY_BOOL;
    }
    if (ty_int(a) && ty_int(b)) {
        if (a >= b) {
            return a;
        }
        return b;
    }
    return TY_BAD;
}

pub fn step_of(nodes: &[u8], text: &[u8], w: usize, va: usize, vb: usize) -> i64 {
    let body: i64 = loop_block(nodes, text, w, "body");
    if (body == NO_NODE) {
        return NO_NODE;
    }
    let bi: usize = (body as _);
    if (assigns_of(nodes, text, (w + 1), end(nodes, w), va, vb) != 1) {
        return NO_NODE;
    }
    let ce: i64 = loop_block(nodes, text, w, "continue_expr");
    if (ce != NO_NODE) {
        let cei: usize = (ce as _);
        let mut s: usize = (cei + 1);
        while (s < end(nodes, cei)) {
            let st: i64 = steps_up(nodes, text, s, va, vb);
            if (st != NO_NODE) {
                return st;
            }
            s = end(nodes, s);
        }
        return NO_NODE;
    }
    if own_continue(nodes, (bi + 1), end(nodes, bi)) {
        return NO_NODE;
    }
    let mut s2: usize = (bi + 1);
    while (s2 < end(nodes, bi)) {
        let st2: i64 = steps_up(nodes, text, s2, va, vb);
        if (st2 != NO_NODE) {
            return st2;
        }
        s2 = end(nodes, s2);
    }
    return NO_NODE;
}

pub fn steps_up(nodes: &[u8], text: &[u8], s: usize, va: usize, vb: usize) -> i64 {
    if ((kind(nodes, s) != K_STMT_ASSIGN) || (children(nodes, s) != 2)) {
        return NO_NODE;
    }
    let t: usize = (s + 1);
    let r: usize = end(nodes, t);
    if !(ident_is(nodes, text, t, &text[(va) as usize..(vb) as usize])) {
        return NO_NODE;
    }
    if (field_eq(nodes, text, s, F_OP, "+=") || field_eq(nodes, text, s, F_OP, "+%=")) {
        let ri: i64 = (r as _);
        return ri;
    }
    if (!(field_eq(nodes, text, s, F_OP, "")) && !(field_eq(nodes, text, s, F_OP, "="))) {
        return NO_NODE;
    }
    if ((kind(nodes, r) != K_EXPR_BINARY) || (children(nodes, r) != 2)) {
        return NO_NODE;
    }
    if (!(field_eq(nodes, text, r, F_OP, "+")) && !(field_eq(nodes, text, r, F_OP, "+%"))) {
        return NO_NODE;
    }
    if !(ident_is(nodes, text, (r + 1), &text[(va) as usize..(vb) as usize])) {
        return NO_NODE;
    }
    let c: usize = end(nodes, (r + 1));
    let cc: i64 = (c as _);
    return cc;
}

pub fn trip_bound(op: &[u8], kok: bool, k: u64, sok: bool, step: u64) -> i64 {
    if (((!(kok) || !(sok)) || (step == 0)) || (k > 4611686018427387904)) {
        return NO_BOUND;
    }
    let ki: i64 = (k as _);
    if same(op, "<") {
        return ki;
    }
    if same(op, "<=") {
        return (ki + 1);
    }
    return NO_BOUND;
}

pub fn ty_int(t: i64) -> bool {
    return ((t >= 1) && (t <= MAX_WIDTH));
}

pub fn ty_scalar(t: i64) -> bool {
    return (ty_int(t) || (t == TY_BOOL));
}

pub fn ty_width(t: i64) -> i64 {
    if ty_int(t) {
        return t;
    }
    if (t == TY_BOOL) {
        return 1;
    }
    return 0;
}

pub fn type_code(s: &[u8], a: usize, b: usize) -> i64 {
    let p: usize = trim_lo(s, a, b);
    let q: usize = trim_hi(s, p, b);
    if ((q == p) || same(&s[(p) as usize..(q) as usize], "void")) {
        return TY_VOID;
    }
    if same(&s[(p) as usize..(q) as usize], "bool") {
        return TY_BOOL;
    }
    if same(&s[(p) as usize..(q) as usize], "usize") {
        return 64;
    }
    if same(&s[(p) as usize..(q) as usize], "comptime_int") {
        return TY_COMPTIME;
    }
    if ((same(&s[(p) as usize..(q) as usize], "str") || same(&s[(p) as usize..(q) as usize], "string")) || same(&s[(p) as usize..(q) as usize], "[]const u8")) {
        return TY_STR;
    }
    if ((same(&s[(p) as usize..(q) as usize], "f64") || same(&s[(p) as usize..(q) as usize], "f32")) || same(&s[(p) as usize..(q) as usize], "comptime_float")) {
        return TY_FLOAT;
    }
    if (((s[(p) as usize] != 117) || ((q - p) < 2)) || ((q - p) > 3)) {
        return TY_BAD;
    }
    let p1: usize = (p + 1);
    let mut w: i64 = 0;
    let mut j: usize = p1;
    while (j < q) {
        if !(digit(s[(j) as usize])) {
            return TY_BAD;
        }
        let dv: i64 = ((s[(j) as usize] - 48) as _);
        w = ((w * 10) + dv);
        j = (j + 1);
    }
    if (((s[(p1) as usize] == 48) || (w < 1)) || (w > MAX_WIDTH)) {
        return TY_BAD;
    }
    return w;
}

pub fn verilog_keyword(s: &[u8]) -> bool {
    let mut j: usize = 0;
    while (j < 103) {
        if same(s, VERILOG_KEYWORDS[(j) as usize]) {
            return true;
        }
        j = (j + 1);
    }
    j = 0;
    while (j < 17) {
        if same(s, VERILOG_KEYWORDS_2[(j) as usize]) {
            return true;
        }
        j = (j + 1);
    }
    j = 0;
    while (j < 5) {
        if same(s, VERILOG_KEYWORDS_3[(j) as usize]) {
            return true;
        }
        j = (j + 1);
    }
    return false;
}

pub fn verilog_op(s: &[u8]) -> &'static str {
    if same(s, "+%") {
        return "+";
    }
    if same(s, "-%") {
        return "-";
    }
    if same(s, "*%") {
        return "*";
    }
    if same(s, "and") {
        return "&&";
    }
    if same(s, "or") {
        return "||";
    }
    if same(s, "+") {
        return "+";
    }
    if same(s, "-") {
        return "-";
    }
    if same(s, "*") {
        return "*";
    }
    if same(s, "/") {
        return "/";
    }
    if same(s, "%") {
        return "%";
    }
    if same(s, "&") {
        return "&";
    }
    if same(s, "|") {
        return "|";
    }
    if same(s, "^") {
        return "^";
    }
    if same(s, "<<") {
        return "<<";
    }
    if same(s, ">>") {
        return ">>";
    }
    if same(s, "==") {
        return "==";
    }
    if same(s, "!=") {
        return "!=";
    }
    if same(s, "<") {
        return "<";
    }
    if same(s, "<=") {
        return "<=";
    }
    if same(s, ">") {
        return ">";
    }
    if same(s, ">=") {
        return ">=";
    }
    if same(s, "&&") {
        return "&&";
    }
    if same(s, "||") {
        return "||";
    }
    return "?";
}

